<template>
    <div class="pkg-bar"><span class="pkg-label">应用</span><select v-model="ctx.activePkg" class="select mono pkg-select"><option v-if="!ctx.pkgOptions.length" value="">（未配置应用包名）</option><option v-for="p in ctx.pkgOptions" :key="p" :value="p">{{ p }}</option></select><button class="btn btn-sm" :disabled="!ctx.activePkg" @click="ctx.exportPartition">⬆ 导出</button><button class="btn btn-sm" :disabled="!ctx.activePkg" @click="impFile.click()">⬇ 导入</button><input ref="impFile" type="file" accept=".zip" hidden @change="ctx.onImportFile" /></div>
    <div v-if="!ctx.activePkg" class="pkg-empty">暂无应用分区：请先在「设备」页签配置应用包名（模板与脚本按应用分区存储）</div>
    <template v-else>
      <div class="script-tpl">
        <template v-if="!ctx.crop.active"><div class="tpl-top"><input v-model.number="ctx.testThreshold" class="input input-sm mono" type="number" min="0" max="1" step="0.01" placeholder="测试阈值 0~1" /><select v-model="ctx.testRegion" class="select mono tpl-region"><option value="">默认</option><option value="a">a · 全屏</option><option value="u">u · 上半屏</option><option value="d">d · 下半屏</option><option value="l">l · 左半屏</option><option value="r">r · 右半屏</option><option value="ul">ul · 左上</option><option value="ur">ur · 右上</option><option value="dl">dl · 左下</option><option value="dr">dr · 右下</option></select><input v-model="ctx.tplSearch" class="input input-sm mono tpl-search" placeholder="🔍 模糊/拼音首字母搜索…" /><button class="btn btn-sm" :class="{ active: ctx.picking }" @click="ctx.togglePick" :disabled="!ctx.connected">✂️ 框选</button><button class="btn btn-sm" @click="tplUpload.click()">⬆️ 上传</button><input ref="tplUpload" type="file" accept="image/png,image/jpeg" hidden @change="ctx.onTplUpload" /></div><div class="tpl-list-wrap"><div class="tpl-list-head"><span class="tpl-cell thumb">缩略图</span><span class="tpl-cell name">文件名</span><span class="tpl-cell ops">操作</span></div><div class="tpl-list"><div v-for="t in ctx.templates" :key="t.name" class="tpl-row" :class="{ 'del-confirm': ctx.confirmDelTpl === t.name, renaming: ctx.renaming === t.name }" @click="ctx.onTplRowClick($event, t)"><span class="tpl-cell thumb" @click.stop="ctx.onTplThumbClick($event, t)"><span class="tpl-thumb"><img :src="ctx.tplThumbUrl(t.name)" alt="" loading="lazy" @error="e => e.target.style.visibility = 'hidden'" /></span></span><span class="tpl-cell name mono" @click.stop="ctx.onTplNameClick($event, t)"><input v-if="ctx.renaming === t.name" :ref="el => ctx.setRenameInputEl(el)" v-model="ctx.renameVal" class="input rename-input mono" @keydown.enter="ctx.confirmRename(t)" @keydown.esc="ctx.cancelRename" @blur="ctx.cancelRename" @click.stop /><template v-else>{{ ctx.tplShortName(t.name) }}<span v-if="ctx.tplRegionBadge(t.name)" class="tpl-region-badge">{{ ctx.tplRegionBadge(t.name) }}</span></template></span><span class="tpl-cell ops"><button v-if="ctx.renaming === t.name" class="btn btn-sm btn-primary" @mousedown.prevent @click.stop="ctx.confirmRename(t)">确认</button><button v-else class="btn btn-sm" @click.stop="ctx.startRename(t)">重命名</button><button class="btn btn-sm" :class="{ 'tpl-del-confirm': ctx.confirmDelTpl === t.name }" @click.stop="ctx.onTplDeleteClick(t)">{{ ctx.confirmDelTpl === t.name ? '确认' : '删除' }}</button><button class="btn btn-sm" @click.stop="ctx.onTplMatchClick(t)">匹配</button></span></div><div v-if="!ctx.templates.length" class="tpl-empty">{{ ctx.tplSearch.trim() ? '没有匹配的模板' : '暂无模板，点击「框选」或「上传」创建' }}</div></div></div><div class="tpl-tools"><span class="ps-sub">缩略图 → 查看大图 · alt 模式点文件名 → 生成 find 记录 · 匹配 → 测试匹配 · 重命名 → 修改模板名</span></div></template>
        <div v-else class="crop-panel crop-panel-full" ref="cropSec"><div class="ps-head"><span class="ps-title">✂️ 二次裁切</span><span class="ps-sub mono">{{ ctx.cropSize }} · {{ ctx.cropZoomPct }}</span></div><div class="crop-stage"><canvas ref="cropCanvas" class="crop-canvas" @mousedown="ctx.cropMouseDown" @mousemove="ctx.cropMouseMove" @mouseup="ctx.cropMouseUp" @mouseleave="ctx.cropMouseLeave" @wheel="ctx.cropWheel"></canvas></div><div class="crop-hint">滚轮缩放（50%~800%）· 拖动边框/角调整选框 · Alt/alt 模式点击任意处 → 取色生成 color 记录</div><input v-model="ctx.crop.name" class="input mono" placeholder="模板名称（默认自动生成）" @keydown.enter="ctx.saveTemplate" /><div class="crop-actions"><button class="btn btn-sm" @click="ctx.cancelCrop">取消</button><button class="btn btn-sm btn-ghost" @click="ctx.repick">重新框选</button><button class="btn btn-sm btn-primary" :disabled="ctx.saving" @click="ctx.saveTemplate">{{ ctx.saving ? '保存中…' : '💾 保存模板' }}</button></div></div>
        <div v-if="ctx.viewTpl" class="tpl-view-mask" @click.self="ctx.closeTplView"><div class="tpl-view-modal"><button class="tpl-view-close" @click="ctx.closeTplView">✕</button><div class="tpl-view-img"><img :src="ctx.tplThumbUrl(ctx.viewTpl)" alt="模板预览" /></div><div class="tpl-view-name mono">{{ ctx.viewTpl }}</div></div></div>
      </div>
    </template>
</template>
<script setup>
import { nextTick, onMounted, reactive, ref, watch } from 'vue'
const props = defineProps({ context: { type: Object, required: true }, onCropMounted: { type: Function, required: true } })
const ctx = reactive(props.context); const impFile = ref(null); const tplUpload = ref(null); const cropSec = ref(null); const cropCanvas = ref(null)
async function emitCropRefs() { if (!ctx.crop.active) return; await nextTick(); props.onCropMounted({ canvas: cropCanvas.value, section: cropSec.value }) }
watch(() => ctx.crop.active, emitCropRefs); onMounted(emitCropRefs)
</script>
